        "title": "Latihan 2: Posisi Kata Keterangan Frekuensi (Adverbs of Frequency)",
        "instruction": "Pilihlah susunan kalimat yang benar dengan penempatan kata keterangan frekuensi (always, usually, often, sometimes, rarely, never).",
        "type": "choice",
        "questions": [
          {
            "q": "1. Pilihlah posisi keterangan frekuensi yang tepat untuk kata 'always':",
            "options": [
              "Julia always arrives on time for work.",
              "Julia arrives always on time for work.",
              "Always Julia arrives on time for work.",
              "Julia arrives on time always for work."
            ],
            "answer": "Julia always arrives on time for work.",
            "hint": "Keterangan frekuensi diletakkan sebelum kata kerja utama.",
            "explanation": "Adverb of frequency diletakkan sebelum kata kerja utama (main verb): 'always arrives'."
          },
          {
            "q": "2. Pilihlah posisi yang tepat jika kalimat menggunakan kata kerja 'to be':",
            "options": [
              "They are never late for morning assembly.",
              "They never are late for morning assembly.",
              "Never they are late for morning assembly.",
              "They are late never for morning assembly."
            ],
            "answer": "They are never late for morning assembly.",
            "hint": "Keterangan frekuensi diletakkan SETELAH kata kerja 'to be'.",
            "explanation": "Setelah to be (am/is/are), letakkan adverb of frequency: 'are never late'."
          },
          {
            "q": "3. Pilihlah kalimat negatif dengan keterangan frekuensi yang tepat:",
            "options": [
              "We don't often eat fast food.",
              "We often don't eat fast food.",
              "We don't eat often fast food.",
              "Often we don't eat fast food."
            ],
            "answer": "We don't often eat fast food.",
            "hint": "Di antara kata kerja bantu (auxiliary) dan kata kerja utama.",
            "explanation": "Adverb diletakkan di antara kata bantu 'don't' dan kata kerja utama 'eat': 'don't often eat'."
          },
          {
            "q": "4. Di manakah posisi kata 'sometimes' yang paling tepat dalam kalimat tanya?",
            "options": [
              "Do you sometimes go jogging in the park?",
              "Sometimes do you go jogging in the park?",
              "Do you go sometimes jogging in the park?",
              "Do sometimes you go jogging in the park?"
            ],
            "answer": "Do you sometimes go jogging in the park?",
            "hint": "Antara subjek dan kata kerja utama.",
            "explanation": "Pola kalimat tanya: Do + Subjek (you) + Adverb (sometimes) + Verb (go)?"
          }
        ]
