        "title": "Latihan 1: Bentuk -ing (Gerund) Setelah Preposisi",
        "instruction": "Pilihlah bentuk kata kerja yang tepat setelah kata depan (preposition).",
        "type": "choice",
        "questions": [
          {
            "q": "1. She is exceptionally good at [BLANK] languages.",
            "options": [
              "learning",
              "learn",
              "to learn",
              "learned"
            ],
            "answer": "learning",
            "hint": "Setelah preposisi 'at', kata kerja selalu berbentuk -ing.",
            "explanation": "Aturan emas bahasa Inggris: setelah preposisi (at, in, of, about, for, etc.), kata kerja wajib berbentuk gerund (-ing): 'good at learning'."
          },
          {
            "q": "2. We are interested in [BLANK] ancient Roman history.",
            "options": [
              "studying",
              "study",
              "to study",
              "studied"
            ],
            "answer": "studying",
            "hint": "Setelah preposisi 'in'.",
            "explanation": "Frasa 'interested in' diikuti gerund: 'interested in studying'."
          },
          {
            "q": "3. He left the room without [BLANK] goodbye to anyone.",
            "options": [
              "saying",
              "say",
              "to say",
              "said"
            ],
            "answer": "saying",
            "hint": "Setelah preposisi 'without'.",
            "explanation": "'Without' adalah preposisi sehingga diikuti gerund: 'without saying'."
          },
          {
            "q": "4. Instead of [BLANK] by car, we decided to take the high-speed train.",
            "options": [
              "travelling",
              "travel",
              "to travel",
              "travelled"
            ],
            "answer": "travelling",
            "hint": "Setelah preposisi 'instead of'.",
            "explanation": "Setelah 'instead of', gunakan bentuk -ing: 'instead of travelling'."
          }
        ]
